async function ambilProduk(id: number): Promise<Produk> {
  const json = await fetch(`/api/produk/${id}`).then((r) => r.json());
  const hasil = Produk.safeParse(json);
  if (!hasil.success) throw new Error("Data produk dari server tidak sesuai");
  return hasil.data;
}

