function DaftarUlasan({ produkId }) {
  const [st, setSt] = useState({ memuat: true, error: null, data: [] });
  useEffect(() => {
    fetch(`/api/produk/${produkId}/ulasan`)
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error("HTTP " + r.status))))
      .then((data) => setSt({ memuat: false, error: null, data }))
      .catch((error) => setSt({ memuat: false, error, data: [] }));
  }, [produkId]);

  if (st.memuat) return <p>Memuat ulasan...</p>;
  if (st.error) return <p role="alert">Ulasan gagal dimuat.</p>;
  if (st.data.length === 0) return <p>Belum ada ulasan. Jadilah yang pertama!</p>;
  return <ul>{st.data.map((u) => <li key={u.id}>{u.teks}</li>)}</ul>;
}

